//! 🧪️ Own Part21 retained work preserves one original caller across preparation, tiny-turn validation and close.
use super::*;
use semio_framework_plugin::app_testing::OriginalWorkFixture;
use semio_framework_plugin::retained_command::ArtifactCommandSnapshotRead;
use semio_framework_plugin::{AppOperationContext,HistoryView,NoConfig};
use protocol::ColdMutation;
use crate::editor::ifc2x3_any::{Ifc2x3AnyEditor,Ifc2x3AnyEditCommand};
type Work=Ifc2x3DetailsWork<Ifc2x3AnyEditor>;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1_000_000,maximum_copy_bytes:1_048_576,maximum_capacity_bytes:1_048_576,maximum_release_bytes:1_048_576,maximum_depth:256}}
fn close(caller:&mut OriginalWorkFixture,work:&mut Work){work.begin_close();for _ in 0..8192{if work.terminal_is_empty(){return;}assert!(caller.close(work,grant()).is_ok());}panic!("own Part21 work close did not drain")}
fn fixture()->Arc<Ifc2x3Snapshot>{Arc::new(Ifc2x3Snapshot{document:semio_s_artifact_stdio_contract::part21::Part21Document{instances:vec![Part21Instance{id:1,entities:vec![("IFCPERSON".into(),vec![V::Unset,V::Str("Old".into()),V::Unset,V::Unset,V::Unset,V::Unset,V::Unset,V::Unset])]}],..Default::default()},..Default::default()})}
fn run_input<T>(snapshot:&Arc<Ifc2x3Snapshot>,event:SnapshotEditEvent,caller:&mut OriginalWorkFixture,work:&mut Work,run:impl FnOnce(&ArtifactCommandInputs<'_,EditorApp<Ifc2x3AnyEditor>>,&mut OriginalWorkFixture,&mut Work)->T)->T{let mut command=Ifc2x3AnyEditCommand::EditSnapshot{event};assert!(caller.work_turn(grant(),1_000_000,|cx|work.receive_original_command(&mut command,cx)).unwrap());let config=NoConfig{};let history=HistoryView::empty();let interaction=Default::default();let hover=Default::default();let operation=AppOperationContext{app_instance_id:17,parent_document_id:"own-part21-work".into(),operation_id:716,generation:3,canonical_base_revision:[0;32],retained:grant(),authoring_seed:"own-part21-work".into()};let input=ArtifactCommandInputs{command:&command,snapshot:snapshot.as_ref(),snapshot_owner:Some(snapshot),snapshot_read:ArtifactCommandSnapshotRead::unavailable(&operation),config:&config,history:&history,interaction:&interaction,hover:&hover,context:None,operation:&operation};run(&input,caller,work)}
#[test]
fn own_part21_real_work_resumes_domain_at_original_fuel_one_and_restores_inverse(){let snapshot=fixture();let original=snapshot.as_ref().clone();let text="A Unicode 😀 family name across tiny turns";let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/1/value".into(),value:DslValue::String(text.into())};let mut caller=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(716),semio_framework_job::Generation(3));let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);run_input(&snapshot,event,&mut caller,&mut work,|input,caller,work|{for _ in 0..8192{if work.pending.is_some(){break;}let step=caller.work_turn(grant(),1_000_000,|cx|work.step(input,cx)).unwrap();assert!(!matches!(step,ArtifactCommandWorkStep::Complete(_)));}assert!(work.pending.is_some());let mut turns=0;while !work.domain_done{turns+=1;assert!(turns<4096);let step=caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap();assert!(!matches!(step,ArtifactCommandWorkStep::Complete(_)));}assert!(turns>text.chars().count());assert_eq!(snapshot.as_ref(),&original);let mut emit=None;for _ in 0..128{let step=caller.work_turn(grant(),1_000_000,|cx|work.step(input,cx)).unwrap();if let ArtifactCommandWorkStep::Complete(done)=step{emit=Some(done);break;}}let mutations=emit.unwrap().artifact_mutations;assert_eq!(mutations.len(),1);let mutation=&mutations[0];let inverse=mutation.inverse(&original).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&original).diff(),&original).unwrap();for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert_eq!(next,original);close(caller,work);assert!(work.terminal_is_empty());});caller.finish();assert_eq!(Arc::strong_count(&snapshot),1);}
#[test]
fn own_part21_real_pending_domain_zero_fuel_and_cancel_never_publish(){for cancelled in [false,true]{let snapshot=fixture();let original=snapshot.as_ref().clone();let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/1/value".into(),value:DslValue::String("Changed".into())};let mut caller=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(716),semio_framework_job::Generation(3));let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);run_input(&snapshot,event,&mut caller,&mut work,|input,caller,work|{for _ in 0..8192{if work.pending.is_some(){break;}caller.work_turn(grant(),1_000_000,|cx|work.step(input,cx)).unwrap();}assert!(work.pending.is_some());if cancelled{caller.cancel().cancel_now();}let result=caller.work_turn(grant(),if cancelled{1_000_000}else{0},|cx|work.step(input,cx));assert!(!matches!(result,Ok(ArtifactCommandWorkStep::Complete(_))));assert_eq!(snapshot.as_ref(),&original);close(caller,work);assert!(work.terminal_is_empty());});caller.finish();assert_eq!(Arc::strong_count(&snapshot),1);}}

fn prepared(caller:&mut OriginalWorkFixture,work:&mut Work,input:&ArtifactCommandInputs<'_,EditorApp<Ifc2x3AnyEditor>>)->usize{for turn in 0..200_000{if work.pending.is_some(){return turn;}let result=caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap();assert!(!matches!(result,ArtifactCommandWorkStep::Complete(_)));}panic!("Own Part21 native preparation did not finish")}
fn emitted(caller:&mut OriginalWorkFixture,work:&mut Work,input:&ArtifactCommandInputs<'_,EditorApp<Ifc2x3AnyEditor>>)->Vec<Ifc2x3Mutation>{for _ in 0..200_000{if let ArtifactCommandWorkStep::Complete(emit)=caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap(){return emit.artifact_mutations;}}panic!("Own Part21 original work did not publish")}
fn restores(original:&Ifc2x3Snapshot,mutations:&[Ifc2x3Mutation])->Ifc2x3Snapshot{let mut next=original.clone();let mut inverses=Vec::new();for mutation in mutations{let inverse=mutation.inverse(&next).unwrap();next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();inverses.push(inverse);}let edited=next.clone();for inverse in inverses.into_iter().rev(){for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}}assert_eq!(next,*original);edited}
#[test]
fn preparation_vectors_preserve_large_siblings_typed_decimal_order_and_selected_reference(){let fixture=semio_framework_pack_json::parse(include_str!("🧪️tests/preparation.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for(index,row)in fixture["cases"].as_array().unwrap().iter().enumerate(){let name=row["entity"].as_str().unwrap();let argument=row["argument"].as_u64().unwrap()as usize;let attributes=catalog::ifc2x3_attribute_declarations(name).unwrap();let mut args=vec![V::Unset;attributes.len()];let mut instances=Vec::new();let(path,value,insert)=match index{0=>{let sibling=&row["sibling"];args[sibling["argument"].as_u64().unwrap()as usize]=V::Real(Part21Decimal{negative:sibling["negative"].as_bool().unwrap(),coefficient:"7".repeat(sibling["coefficientDigits"].as_u64().unwrap()as usize),scale:sibling["scale"].as_u64().unwrap()as u32,exponent:Some(sibling["exponent"].as_i64().unwrap()as i32)});args[argument]=V::Str("Old".into());(format!("/ifc-1/entities/0/arguments/{argument}/value"),DslValue::String(row["text"].as_str().unwrap().into()),false)},1=>(format!("/document/instances/0/entities/0/arguments/{argument}"),semio_framework_pack_json::to_dsl_value(&row["value"]),false),2=>{args[argument]=V::List(row["before"].as_array().unwrap().iter().map(|value|V::Real(Part21Decimal{negative:false,coefficient:value.as_str().unwrap().into(),scale:0,exponent:None})).collect());(format!("/document/instances/0/entities/0/arguments/{argument}/values/{}",row["insert"].as_u64().unwrap()),V::Real(Part21Decimal{negative:false,coefficient:row["value"].as_str().unwrap().into(),scale:0,exponent:None}).to_value(),true)},_=>{instances.push(Part21Instance{id:u64::MAX,entities:vec![("IFCLOCALPLACEMENT".into(),Vec::new())]});(format!("/ifc-1/entities/0/arguments/{argument}/reference"),DslValue::String(row["target"].as_str().unwrap().into()),false)}};instances.insert(0,Part21Instance{id:1,entities:vec![(name.into(),args)]});let snapshot=Arc::new(Ifc2x3Snapshot{document:semio_s_artifact_stdio_contract::part21::Part21Document{instances,..Default::default()},..Default::default()});let original=snapshot.as_ref().clone();let event=if insert{SnapshotEditEvent::InsertValue{path,value}}else{SnapshotEditEvent::SetValue{path,value}};let mut caller=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(716),semio_framework_job::Generation(3));let mut work=Work::new(if insert{editing::INSERT_SNAPSHOT_VALUE_ACTION_ID}else{editing::SET_SNAPSHOT_VALUE_ACTION_ID});run_input(&snapshot,event,&mut caller,&mut work,|input,caller,work|{let turns=prepared(caller,work,input);assert!(turns>8);let mutations=emitted(caller,work,input);assert_eq!(mutations.len(),1);let edited=restores(&original,&mutations);if index==0{assert_eq!(edited.document.instances[0].entities[0].1[3],original.document.instances[0].entities[0].1[3]);}if index==1{assert_eq!(edited.document.instances[0].entities[0].1[argument],V::from_value(semio_framework_pack_json::to_dsl_value(&row["value"])).unwrap());}if index==2{assert_eq!(edited.document.instances[0].entities[0].1[argument],V::List(row["after"].as_array().unwrap().iter().map(|value|V::Int(value.as_str().unwrap().parse().unwrap())).collect()));}if index==3{assert_eq!(edited.document.instances[0].entities[0].1[argument],V::Ref(u64::MAX));}assert_eq!(snapshot.as_ref(),&original);close(caller,work);});caller.finish();assert_eq!(Arc::strong_count(&snapshot),1);}}
#[test]
fn funded_part21_subtree_receiver_preserves_canonical_binary_policy_and_failed_owner_close(){let vectors=semio_framework_pack_json::parse(include_str!("../../../../../../../../📇️registry/🧬️contract/📐️part21/🫴️receiving/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in vectors["binary"].as_array().unwrap(){let text=row["value"].as_str().unwrap();let value=V::List(vec![V::Binary(text.into())]).to_value();let snapshot=fixture();let original=snapshot.as_ref().clone();let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/3".into(),value};let mut caller=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(716),semio_framework_job::Generation(3));let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);run_input(&snapshot,event,&mut caller,&mut work,|input,caller,work|{let mut admitted=false;for _ in 0..10_000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Err(_)=>break,Ok(ArtifactCommandWorkStep::Complete(_))=>panic!("binary receiver test must stop before publication"),Ok(_)=>{if work.pending.is_some(){admitted=true;break;}}}}assert_eq!(admitted,row["admitted"].as_bool().unwrap(),"{text}");assert_eq!(snapshot.as_ref(),&original);close(caller,work);});caller.finish();assert_eq!(Arc::strong_count(&snapshot),1);}}

#[test]
fn native_type_changes_resume_original_fuel_one_and_reconcile_complex_derived_slots(){let fixture=semio_framework_pack_json::parse(include_str!("🧪️tests/preparation.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixture["typeChanges"].as_array().unwrap(){let complex=row["complex"].as_bool().unwrap();let instances=if complex{vec![Part21Instance{id:1,entities:vec![("IFCNAMEDUNIT".into(),vec![V::Derived,V::Enum("LENGTHUNIT".into())]),("IFCSIUNIT".into(),vec![V::Unset,V::Enum("METRE".into())])]},Part21Instance{id:2,entities:vec![("IFCDIMENSIONALEXPONENTS".into(),vec![V::Int(0);7])]}]}else{vec![Part21Instance{id:1,entities:vec![("IFCWALL".into(),vec![V::Str("0123456789012345678901".into()),V::Unset,V::Str("kept ".repeat(1024)),V::Real(Part21Decimal{negative:true,coefficient:"123456789012345678901234567890".into(),scale:19,exponent:Some(-99)}),V::Unset,V::Unset,V::Unset,V::Str("tag".into())])]}]};let snapshot=Arc::new(Ifc2x3Snapshot{document:semio_s_artifact_stdio_contract::part21::Part21Document{instances,..Default::default()},..Default::default()});let original=snapshot.as_ref().clone();let event=SnapshotEditEvent::SetValue{path:format!("/ifc-1/entities/{}/typeName",row["part"].as_u64().unwrap()),value:DslValue::String(row["to"].as_str().unwrap().into())};let mut caller=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(716),semio_framework_job::Generation(3));let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);run_input(&snapshot,event,&mut caller,&mut work,|input,caller,work|{assert!(prepared(caller,work,input)>16);let mutations=emitted(caller,work,input);let edited=restores(&original,&mutations);assert_eq!(edited.document.instances[0].entities[row["part"].as_u64().unwrap()as usize].0,row["to"].as_str().unwrap());if complex{assert_eq!(edited.document.instances[0].entities[0].1[0],V::Ref(row["dimensionTarget"].as_str().unwrap().parse().unwrap()));}else{assert_eq!(edited.document.instances[0].entities[0].1[2],original.document.instances[0].entities[0].1[2]);assert_eq!(edited.document.instances[0].entities[0].1[3],original.document.instances[0].entities[0].1[3]);}close(caller,work);});caller.finish();assert_eq!(Arc::strong_count(&snapshot),1);}}
